=== FILE: tb_debounce_fall_restart.v ===
// Repro: a change on noisy in either direction must restart the debounce count,
// so a low pulse shorter than STABLE edges must never reach clean.
`timescale 1ns / 1ps
module tb_debounce_fall_restart;
    reg  clk   = 1'b0;
    reg  rst   = 1'b1;
    reg  noisy = 1'b0;
    wire clean;

    integer passed = 0;
    integer failed = 0;
    integer i;
    reg     glitched;
    reg [8*64-1:0] nonce;

    debounce #(.STABLE(4)) dut (
        .clk(clk), .rst(rst), .noisy(noisy), .clean(clean)
    );

    always #5 clk = ~clk;

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = "none";

        // Reset
        repeat (3) @(negedge clk);
        rst = 1'b0;

        // Hold noisy high well past STABLE edges: clean must become 1.
        noisy = 1'b1;
        repeat (20) @(negedge clk);
        if (clean === 1'b1) passed = passed + 1;
        else begin
            failed = failed + 1;
            $display("FAIL: clean=%b after long high, expected 1", clean);
        end

        // Low pulse of 2 edges (< STABLE): clean must stay 1 throughout.
        glitched = 1'b0;
        noisy = 1'b0;
        for (i = 0; i < 14; i = i + 1) begin
            @(negedge clk);
            if (i == 1) noisy = 1'b1;
            if (clean !== 1'b1) glitched = 1'b1;
        end
        if (!glitched) passed = passed + 1;
        else begin
            failed = failed + 1;
            $display("FAIL: a 2-edge low pulse reached clean (spec: pulses of STABLE edges or fewer never reach clean)");
        end

        // Hold noisy low well past STABLE edges: clean must become 0.
        noisy = 1'b0;
        repeat (20) @(negedge clk);
        if (clean === 1'b0) passed = passed + 1;
        else begin
            failed = failed + 1;
            $display("FAIL: clean=%b after long low, expected 0", clean);
        end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
